class Solution { public:
 vector<int> timeTaken(vector<vector<int>>& edges) {
  int n=edges.size()+1;vector<vector<int>> g(n);for(auto &e:edges){g[e[0]].push_back(e[1]);g[e[1]].push_back(e[0]);}
  vector<int> par(n,-1),order={0},down(n),up(n);par[0]=0;
  for(int i=0;i<(int)order.size();++i){int u=order[i];for(int v:g[u])if(v!=par[u]){par[v]=u;order.push_back(v);}}
  for(int i=n-1;i>=0;--i){int u=order[i];for(int v:g[u])if(v!=par[u])down[u]=max(down[u],(v%2?1:2)+down[v]);}
  for(int u:order){int mx1=0,mx2=0,who=-1;for(int v:g[u])if(v!=par[u]){int x=(v%2?1:2)+down[v];if(x>mx1){mx2=mx1;mx1=x;who=v;}else mx2=max(mx2,x);}
   for(int v:g[u])if(v!=par[u])up[v]=(u%2?1:2)+max(up[u],v==who?mx2:mx1);
  }
  vector<int> ans(n);for(int i=0;i<n;++i)ans[i]=max(down[i],up[i]);return ans;
 }
};
